/* Dominant eigenpair of a real n x n matrix (n <= 10).
 * Hessenberg reduction (Householder) + shifted complex QR (Givens),
 * then inverse iteration for the eigenvector of the dominant eigenvalue.
 */
#include <math.h>
#include <complex.h>
#include <string.h>

#define MAXN 10
typedef double complex cx;

static inline double cabs2(cx z) { double r = creal(z), i = cimag(z); return r*r + i*i; }
static inline double cabsv(cx z) { return sqrt(cabs2(z)); }

static void solve2x2(cx a, cx b, cx c, cx d, cx *l1, cx *l2) {
    cx half = (a + d) * 0.5;
    cx disc = ((a - d) * (a - d)) * 0.25 + b * c;
    cx q = csqrt(disc);
    *l1 = half + q;
    *l2 = half - q;
}

/* One implicit shifted QR step on the leading m x m upper Hessenberg block. */
static void qr_step(cx H[MAXN][MAXN], int m, cx mu) {
    cx cs[MAXN], sn[MAXN];
    for (int i = 0; i < m; i++) H[i][i] -= mu;
    for (int k = 0; k < m - 1; k++) {
        cx a = H[k][k], b = H[k+1][k];
        double r = sqrt(cabs2(a) + cabs2(b));
        cx c, s;
        if (r == 0.0) { c = 1.0; s = 0.0; }
        else { c = conj(a) / r; s = conj(b) / r; }
        cs[k] = c; sn[k] = s;
        for (int j = k; j < m; j++) {
            cx x = H[k][j], y = H[k+1][j];
            H[k][j]   = c*x + s*y;
            H[k+1][j] = -conj(s)*x + conj(c)*y;
        }
        H[k+1][k] = 0.0;
    }
    for (int k = 0; k < m - 1; k++) {
        cx c = cs[k], s = sn[k];
        for (int i = 0; i <= k + 1 && i < m; i++) {
            cx x = H[i][k], y = H[i][k+1];
            H[i][k]   = conj(c)*x + conj(s)*y;
            H[i][k+1] = -s*x + c*y;
        }
    }
    for (int i = 0; i < m; i++) H[i][i] += mu;
}

/* Real Householder reduction to upper Hessenberg form. */
static void hessenberg(double A[MAXN][MAXN], int n) {
    double v[MAXN];
    for (int k = 0; k < n - 2; k++) {
        double norm = 0.0;
        for (int i = k + 1; i < n; i++) norm += A[i][k]*A[i][k];
        norm = sqrt(norm);
        if (norm == 0.0) continue;
        double alpha = (A[k+1][k] >= 0.0) ? -norm : norm;
        v[0] = A[k+1][k] - alpha;
        for (int i = k + 2; i < n; i++) v[i-k-1] = A[i][k];
        double vn2 = 0.0;
        for (int i = k + 1; i < n; i++) { double t = v[i-k-1]; vn2 += t*t; }
        if (vn2 == 0.0) continue;
        double beta = 2.0 / vn2;
        for (int j = k; j < n; j++) {
            double dot = 0.0;
            for (int i = k + 1; i < n; i++) dot += v[i-k-1]*A[i][j];
            double t = beta*dot;
            for (int i = k + 1; i < n; i++) A[i][j] -= t*v[i-k-1];
        }
        for (int i = 0; i < n; i++) {
            double dot = 0.0;
            for (int j = k + 1; j < n; j++) dot += A[i][j]*v[j-k-1];
            double t = beta*dot;
            for (int j = k + 1; j < n; j++) A[i][j] -= t*v[j-k-1];
        }
        A[k+1][k] = alpha;
        for (int i = k + 2; i < n; i++) A[i][k] = 0.0;
    }
}

/* All eigenvalues of the Hessenberg matrix H. Returns 0 on success. */
static int eig_qr(cx H[MAXN][MAXN], int n, cx *eig) {
    int m = n;
    while (m > 0) {
        if (m == 1) { eig[0] = H[0][0]; break; }
        int iters = 0;
        for (;;) {
            double sc = cabsv(H[m-2][m-2]) + cabsv(H[m-1][m-1]);
            double thr = 2.3e-16 * sc + 1e-300;
            if (cabsv(H[m-1][m-2]) <= thr) {
                eig[m-1] = H[m-1][m-1];
                m -= 1;
                break;
            }
            if (m == 2) {
                solve2x2(H[0][0], H[0][1], H[1][0], H[1][1], &eig[0], &eig[1]);
                m = 0;
                break;
            }
            double sc2 = cabsv(H[m-3][m-3]) + cabsv(H[m-2][m-2]);
            double thr2 = 2.3e-16 * sc2 + 1e-300;
            if (cabsv(H[m-2][m-3]) <= thr2) {
                solve2x2(H[m-2][m-2], H[m-2][m-1], H[m-1][m-2], H[m-1][m-1],
                         &eig[m-2], &eig[m-1]);
                m -= 2;
                break;
            }
            if (iters >= 400) return -1;
            cx mu1, mu2, mu;
            solve2x2(H[m-2][m-2], H[m-2][m-1], H[m-1][m-2], H[m-1][m-1], &mu1, &mu2);
            if ((iters % 10) == 9) {
                mu = H[m-1][m-1] + 0.75 * cabsv(H[m-1][m-2]);
            } else {
                mu = (cabsv(mu1 - H[m-1][m-1]) < cabsv(mu2 - H[m-1][m-1])) ? mu1 : mu2;
            }
            qr_step(H, m, mu);
            iters++;
        }
    }
    return 0;
}

static void matvec(const double A[MAXN][MAXN], int n, const cx *x, cx *y) {
    for (int i = 0; i < n; i++) {
        double sr = 0.0, si = 0.0;
        for (int j = 0; j < n; j++) {
            double a = A[i][j];
            sr += a * creal(x[j]);
            si += a * cimag(x[j]);
        }
        y[i] = sr + si * I;
    }
}

static int lu_factor(cx M[MAXN][MAXN], int n, int *piv) {
    for (int k = 0; k < n; k++) {
        int p = k;
        double best = cabs2(M[k][k]);
        for (int i = k+1; i < n; i++) {
            double val = cabs2(M[i][k]);
            if (val > best) { best = val; p = i; }
        }
        piv[k] = p;
        if (best == 0.0 || !isfinite(best)) return -1;
        if (p != k) {
            for (int j = 0; j < n; j++) { cx t = M[k][j]; M[k][j] = M[p][j]; M[p][j] = t; }
        }
        cx inv = 1.0 / M[k][k];
        for (int i = k+1; i < n; i++) {
            cx f = M[i][k] * inv;
            M[i][k] = f;
            if (f != 0.0)
                for (int j = k+1; j < n; j++) M[i][j] -= f * M[k][j];
        }
    }
    return 0;
}

static void lu_solve(const cx M[MAXN][MAXN], int n, const int *piv, cx *b) {
    for (int k = 0; k < n; k++) {
        if (piv[k] != k) { cx t = b[k]; b[k] = b[piv[k]]; b[piv[k]] = t; }
    }
    for (int k = 0; k < n; k++)
        for (int i = k+1; i < n; i++) b[i] -= M[i][k] * b[k];
    for (int k = n-1; k >= 0; k--) {
        cx s = b[k];
        for (int j = k+1; j < n; j++) s -= M[k][j] * b[j];
        b[k] = s / M[k][k];
    }
}

/* Inverse iteration for the eigenvector belonging to lam.
 * Accepts only if the residual passes a strict version of np.allclose
 * (atol=1e-8, rtol=1e-5). */
static int eigenvector(const double A[MAXN][MAXN], int n, cx lam,
                       double normA, cx *v) {
    cx M[MAXN][MAXN];
    int piv[MAXN];
    double delta = 1e-12 * (normA + 1.0);
    cx mu = lam + delta;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            M[i][j] = A[i][j] - ((i == j) ? mu : 0.0);
    if (lu_factor(M, n, piv) != 0) return -1;

    unsigned long long s = 0x9e3779b97f4a7c15ULL ^ (unsigned long long)n;
    cx b[MAXN];
    for (int i = 0; i < n; i++) {
        s = s * 6364136223846793005ULL + 1442695040888963407ULL;
        double r1 = (double)(s >> 11) * (1.0 / 9007199254740992.0) - 0.5;
        s = s * 6364136223846793005ULL + 1442695040888963407ULL;
        double r2 = (double)(s >> 11) * (1.0 / 9007199254740992.0) - 0.5;
        b[i] = r1 + r2 * I;
    }
    for (int it = 0; it < 5; it++) {
        lu_solve(M, n, piv, b);
        double nrm = 0.0;
        for (int i = 0; i < n; i++) nrm += cabs2(b[i]);
        nrm = sqrt(nrm);
        if (!(nrm > 0.0) || !isfinite(nrm)) return -1;
        for (int i = 0; i < n; i++) b[i] /= nrm;

        cx y[MAXN];
        matvec(A, n, b, y);
        double worst = 0.0;
        int good = 1;
        for (int i = 0; i < n; i++) {
            cx r = y[i] - lam * b[i];
            double rv = cabsv(r);
            double lv = cabsv(lam * b[i]);
            double tol = 1e-8 + 1e-5 * lv;
            if (!(rv <= 0.01 * tol)) { good = 0; }
            double ratio = rv / tol;
            if (!isfinite(ratio)) return -1;
            if (ratio > worst) worst = ratio;
        }
        if (good) {
            for (int i = 0; i < n; i++) v[i] = b[i];
            return 0;
        }
    }
    return -1;
}

/* Entry point.  A is row-major n*n float64.  lam and v are complex128
 * (interleaved re,im).  Returns 0 on success, nonzero otherwise. */
int dominant_eig(const double *Aflat, int n, cx *lam_out, cx *v_out) {
    if (n < 1 || n > MAXN) return -2;
    double A[MAXN][MAXN];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            double x = Aflat[i*n + j];
            if (!isfinite(x)) return -3;
            A[i][j] = x;
        }
    double normA = 0.0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) normA += A[i][j]*A[i][j];
    normA = sqrt(normA);
    if (!(normA > 0.0) || !isfinite(normA)) return -3;

    double Hr[MAXN][MAXN];
    memcpy(Hr, A, sizeof(Hr));
    hessenberg(Hr, n);
    cx H[MAXN][MAXN];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) H[i][j] = Hr[i][j];

    cx eig[MAXN];
    if (eig_qr(H, n, eig) != 0) return -1;
    for (int i = 0; i < n; i++)
        if (!isfinite(creal(eig[i])) || !isfinite(cimag(eig[i]))) return -1;

    int bi = 0;
    double bm = cabs2(eig[0]);
    for (int i = 1; i < n; i++) {
        double m = cabs2(eig[i]);
        if (m > bm) { bm = m; bi = i; }
    }
    cx lam = eig[bi];
    if (eigenvector(A, n, lam, normA, v_out) != 0) return -4;
    *lam_out = lam;
    return 0;
}
